=== FILE: deep_counter_props.sv ===
// Formal properties for deep_counter, written from interface_spec.md
// (rules DC-RESET, DC-CLEAR, DC-COUNT, DC-HOLD, DC-RANGE, DC-CARRY).
// Immediate assertions only, in clocked or combinational always blocks.
// No assume statements: every input is free on every cycle.
`default_nettype none

module deep_counter_props #(
    parameter integer LIMIT = 99
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    wire [6:0] count;
    wire       carry;

    deep_counter #(.LIMIT(LIMIT)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .en    (en),
        .clr   (clr),
        .count (count),
        .carry (carry)
    );

    // First-cycle guard for $past.
    reg f_past_valid;
    initial f_past_valid = 1'b0;

    // Set on the edge at which a reset is applied (count clears on that edge).
    reg f_reset_seen;
    initial f_reset_seen = 1'b0;

    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_seen <= 1'b1;
    end

    // Clocked rules: next count as a function of the inputs at the edge.
    always @(posedge clk) begin
        if (f_past_valid) begin
            // DC-RESET: rst_n low at an edge clears count.
            if (!$past(rst_n))
                assert (count == 7'd0);

            // DC-CLEAR: rst_n high and clr high clears count, whatever en is.
            if ($past(rst_n) && $past(clr))
                assert (count == 7'd0);

            // DC-COUNT (below LIMIT): count goes up by one.
            if ($past(rst_n) && !$past(clr) && $past(en) && ($past(count) < LIMIT))
                assert (count == $past(count) + 7'd1);

            // DC-COUNT (at LIMIT): count wraps to 0.
            if ($past(rst_n) && !$past(clr) && $past(en) && ($past(count) == LIMIT))
                assert (count == 7'd0);

            // DC-HOLD: no clear, no enable, count unchanged.
            if ($past(rst_n) && !$past(clr) && !$past(en))
                assert (count == $past(count));
        end
    end

    // Combinational rules.
    always @(*) begin
        // DC-RANGE: never above LIMIT once a reset has been applied.
        if (f_reset_seen)
            assert (count <= LIMIT);

        // DC-CARRY: exactly en high, clr low and count at LIMIT, with no edge.
        assert (carry == (en && !clr && (count == LIMIT)));
    end

    // Covers: scenarios the proof must still allow.
    always @(posedge clk) begin
        // Two inputs at once: clear and enable together while out of reset.
        cover (rst_n && clr && en);

        if (f_reset_seen) begin
            // Post-reset wrap edge: count reached LIMIT with en high, clr low.
            cover (carry);
            // Clear beats count at the top count.
            cover (rst_n && clr && en && (count == LIMIT));
        end

        // The wrap itself observed after reset: carry on the last edge, now 0.
        if (f_past_valid && $past(f_reset_seen) && $past(rst_n) && $past(carry))
            cover (count == 7'd0);

        // Hold of a non-zero count after reset.
        if (f_past_valid && $past(f_reset_seen) && $past(rst_n) && !$past(clr) && !$past(en))
            cover (count != 7'd0);
    end
endmodule

// Formal top: the approved RTL at the minimum, default and maximum LIMIT.
module deep_counter_formal (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    deep_counter_props #(.LIMIT(1))   p_min (.clk(clk), .rst_n(rst_n), .en(en), .clr(clr));
    deep_counter_props #(.LIMIT(99))  p_def (.clk(clk), .rst_n(rst_n), .en(en), .clr(clr));
    deep_counter_props #(.LIMIT(127)) p_max (.clk(clk), .rst_n(rst_n), .en(en), .clr(clr));
endmodule

`default_nettype wire
=== END FILE ===
